const body = $input.first().json.body ?? $input.first().json;
const task = body.task || {};
const employee = body.employee || {};
const rawTab = (employee.sheetTabName || employee.name || 'Employee_Tasks').toString();
const safeTab = rawTab.replace(/[:\\/?*[\]]/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 80) || 'Employee_Tasks';

return [{
  json: {
    event: body.event || 'task.created',
    timestamp: body.timestamp || new Date().toISOString(),
    appUrl: body.appUrl || '',
    spreadsheetId: body.googleSpreadsheetId || 'YOUR_GOOGLE_SPREADSHEET_ID',
    mappingSheetName: body.mappingSheetName || 'Employees_Telegram_Map',
    taskCode: task.taskCode || task.id || 'LMR-000',
    title: task.title || 'مهمة جديدة',
    description: task.description || '',
    department: task.department || '',
    projectName: task.projectName || 'عام',
    priority: task.priority || 'Medium',
    priorityAr: task.priorityAr || task.priority || 'متوسطة',
    status: task.status || 'Pending',
    statusAr: task.statusAr || task.status || 'قيد الانتظار',
    completionPercentage: Number(task.completionPercentage ?? 0),
    startDate: task.startDate || '',
    deadline: task.deadline || '',
    createdDate: task.createdDate || (body.timestamp || '').slice(0, 10),
    employeeName: employee.name || '',
    employeeEmail: (employee.email || '').toLowerCase().trim(),
    fallbackSheetTab: safeTab
  }
}];

const taskData = $('تجهيز بيانات المهمة').first().json;
const mapRow = $input.first()?.json || {};
const mappedTab = (mapRow.sheet_tab_name || '').toString().trim();
const targetSheetTab = (mappedTab || taskData.fallbackSheetTab || 'Employee_Tasks')
  .replace(/[:\\/?*[\]]/g, ' ')
  .replace(/\s+/g, ' ')
  .trim()
  .slice(0, 80);

const telegramChatId = (mapRow.telegram_chat_id || '').toString().trim();

const telegramMessage = [
  '📌 *مهمة جديدة من نظام Luméré*',
  '',
  '*الكود:* ' + taskData.taskCode,
  '*العنوان:* ' + taskData.title,
  '*المشروع:* ' + taskData.projectName,
  '*القسم:* ' + taskData.department,
  '*الأولوية:* ' + taskData.priorityAr,
  '*تاريخ البداية:* ' + taskData.startDate,
  '*تاريخ الديدلاين:* ' + taskData.deadline,
  taskData.description ? ('\n*التفاصيل:*\n' + taskData.description) : ''
].filter(Boolean).join('\n');

const gmailHtml = `
<div dir="rtl" style="font-family:Tahoma,Arial,sans-serif;background:#f8fafc;padding:24px;color:#0f172a;">
  <div style="max-width:600px;margin:0 auto;background:#ffffff;border:1px solid #e2e8f0;border-radius:12px;padding:24px;">
    <p style="font-size:12px;color:#059669;font-weight:bold;margin:0 0 8px;">LUMÉRÉ — نظام إدارة المهام</p>
    <h2 style="margin:0 0 16px;font-size:20px;">مهمة جديدة: ${taskData.title}</h2>
    <p style="margin:0 0 16px;color:#334155;">مرحبًا <strong>${taskData.employeeName}</strong>، تم إسناد مهمة جديدة إليك بالتفاصيل التالية:</p>
    <table style="width:100%;border-collapse:collapse;font-size:14px;margin-bottom:16px;">
      <tr><td style="padding:8px;border-bottom:1px solid #e2e8f0;color:#64748b;">كود المهمة</td><td style="padding:8px;border-bottom:1px solid #e2e8f0;font-weight:bold;">${taskData.taskCode}</td></tr>
      <tr><td style="padding:8px;border-bottom:1px solid #e2e8f0;color:#64748b;">القسم / المشروع</td><td style="padding:8px;border-bottom:1px solid #e2e8f0;">${taskData.department} · ${taskData.projectName}</td></tr>
      <tr><td style="padding:8px;border-bottom:1px solid #e2e8f0;color:#64748b;">الأولوية</td><td style="padding:8px;border-bottom:1px solid #e2e8f0;font-weight:bold;">${taskData.priorityAr}</td></tr>
      <tr><td style="padding:8px;border-bottom:1px solid #e2e8f0;color:#64748b;">تاريخ البداية</td><td style="padding:8px;border-bottom:1px solid #e2e8f0;">${taskData.startDate}</td></tr>
      <tr><td style="padding:8px;border-bottom:1px solid #e2e8f0;color:#64748b;">تاريخ الديدلاين</td><td style="padding:8px;border-bottom:1px solid #e2e8f0;color:#dc2626;font-weight:bold;">${taskData.deadline}</td></tr>
    </table>
    ${taskData.description ? `<div style="background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px;padding:12px;font-size:14px;line-height:1.7;">${taskData.description}</div>` : ''}
  </div>
</div>`;

return [{
  json: {
    ...taskData,
    targetSheetTab,
    telegramChatId,
    telegramMessage,
    gmailHtml
  }
}];

const d = $('دمج البيانات وتنسيق الرسائل').first().json;
return [{
  json: {
    task_code: d.taskCode,
    title: d.title,
    department: d.department,
    project: d.projectName,
    priority: d.priorityAr,
    status: d.statusAr,
    progress_pct: d.completionPercentage,
    created_date: d.createdDate,
    start_date: d.startDate,
    deadline: d.deadline,
    employee_email: d.employeeEmail,
    updated_at: d.timestamp
  }
}];

const d = $('دمج البيانات وتنسيق الرسائل').first().json;
return [{
  json: {
    task_code: d.taskCode,
    title: d.title,
    department: d.department,
    project: d.projectName,
    priority: d.priorityAr,
    status: d.statusAr,
    progress_pct: d.completionPercentage,
    created_date: d.createdDate,
    start_date: d.startDate,
    deadline: d.deadline,
    employee_email: d.employeeEmail,
    updated_at: d.timestamp
  }
}];
